    requires value != null && value != ""
    // The input must be a valid string representation of a number.
    ensures result == RoundAwayFromZero(ParseFloat(value))
    // The result is the closest integer to the parsed float value, 
    // rounding away from zero in the case of a tie.

method ParseFloat(value: string) returns (num: real)
    requires value != null && value != ""
    // The input must be a valid string representation of a number.
    ensures num == ToReal(value)

method RoundAwayFromZero(num: real) returns (rounded: int)
    requires num >= -2^31 && num <= 2^31 - 1
    // The input number must be within the range of an integer.
    ensures rounded == if num > 0 then (num + 0.5).floor() else (num - 0.5).ceil()
    // The rounding behavior correctly rounds away from zero for equidistant cases.
